/// C-FFI dispatch descriptor for SunSpec model 702. A C `SunspecModelBinding` points
/// at this static, so the service functions dispatch with no model-id lookup.
#[unsafe(no_mangle)]
pub static SUNSPEC_MODEL_702: StaticModelSpec = StaticModelSpec {
    id: 702,
    length: model_702_c_length,
    writable: true,
    visit_read: model_702_c_visit_read,
    visit_write: model_702_c_visit_write,
};

fn model_702_c_length(_repeat_count_0: u16, _repeat_count_1: u16) -> u16 {
    (Model702).model_length()
}

/// # Safety
/// `adapter` must be null or point to a live `Model702CallbackAdapter`, valid for the
/// duration of the call.
unsafe fn model_702_c_visit_read(
    adapter: *const c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &mut WritableRegisterBuffer<'_>,
) {
    let model = Model702;
    // SAFETY: as required by this function's own contract.
    let adapter = unsafe { (adapter as *const Model702CallbackAdapter).as_ref() };
    cursor.visit_source_block(model.model_length(), |offset, from, len| {
        let mut block = buffer.slice(from, len);
        match adapter {
            Some(adapter) => model.traverse_points_read(adapter, &mut block, offset),
            None => {
                block.fill(&[0xff, 0xff]);
                Ok(())
            }
        }
    });
}

/// # Safety
/// As for [`model_702_c_visit_read`], and `adapter` must be uniquely borrowable for the call.
unsafe fn model_702_c_visit_write(
    adapter: *mut c_void,
    _repeat_count_0: u16,
    _repeat_count_1: u16,
    cursor: &mut Cursor<ModbusException>,
    buffer: &ReadableRegisterBuffer<'_>,
) {
    let model = Model702;
    // SAFETY: as required by this function's own contract.
    let adapter = unsafe { (adapter as *mut Model702CallbackAdapter).as_mut() };
    cursor.visit_source_block(model.model_length(), |offset, from, len| match adapter {
        Some(adapter) => model.traverse_points_write(adapter, &buffer.slice(from, len), offset),
        None => Err(ModbusException::IllegalDataAddress),
    });
}

/// Build a [`SunspecAdapter`] for model 702 backed by a callback adapter.
#[unsafe(no_mangle)]
pub extern "C" fn sunspec_model_702_callback(
    adapter: *mut Model702CallbackAdapter,
) -> SunspecAdapter {
    SunspecAdapter {
        model_spec: &SUNSPEC_MODEL_702,
        adapter: adapter as *mut c_void,
    }
}
